mapper.select:
SELECT 
FROM message
WHERE isDelete = 0
  AND conversationId = #{conversationId}
ORDER BY createTime DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM message
WHERE isDelete = 0
  AND conversationId = #{conversationId}
  AND receiverId = #{receiverId}
  AND status = 0

mapper.update:
UPDATE message
SET status = 1, updateTime = NOW()
WHERE isDelete = 0
  AND conversationId = #{conversationId}
  AND receiverId = #{receiverId}
  AND status = 0

mapper.select:
SELECT DISTINCT conversationId
FROM message
WHERE createTime < #{cutoff}
